"use client";

import type { CSSProperties } from "react";
import {
  Fragment,
  useCallback,
  useEffect,
  useLayoutEffect,
  useMemo,
  useRef,
  useState,
} from "react";
import { createPortal } from "react-dom";
import RestaurantMenu from "@/app/components/restaurant-order/RestaurantMenu";
import { CATERING_CATEGORY_PRESETS } from "@/app/lib/cateringCategories";

// KTT_MEDIA_BLOCK_NOTE: 이미지/비디오는 렌더러에서 block 요소로 유지해
// inline 이미지의 baseline 때문에 생기는 3~4px 하단 틈을 방지합니다.

type CellType =
  | "empty"
  | "logo"
  | "title"
  | "text"
  | "image"
  | "button"
  | "phone"
  | "menu"
  | "sns"
  | "map"
  | "hours";

type TextAlign = "left" | "center" | "right";
type VerticalAlign = "top" | "center" | "bottom";

type OverlayButton = {
  id: string;
  text: string;
  /** 모바일에서만 다른 버튼 문구를 쓰고 싶을 때 사용. 비우면 text 사용 */
  mobile_text?: string;

  /** 버튼 이동 방식: 사이트 페이지 / 현재 페이지 레이어 / 외부 주소 */
  link_type?: "page" | "section" | "external";
  /** page이면 page_slug, section이면 section slug, external이면 URL */
  link_value?: string;

  /** 이전 저장 데이터 호환용 실제 href */
  url: string;
  style: "rounded" | "pill" | "square" | "outline";
  background_color: string;
  text_color: string;
  font_size: number;
  height: number;
  full_width?: boolean;
  x_percent?: number;
  y_percent?: number;

  /** 모바일에서만 사용하는 버튼 위치(%) */
  mobile_x_percent?: number;
  mobile_y_percent?: number;

  /** 페이지 버튼에서 Catering Request Form으로 넘길 카테고리 */
  category_query?: string;
};

type GalleryImageItem = {
  id: string;
  url: string;
  title: string;
};

type VideoCarouselItem = {
  id: string;
  url: string;
  title: string;
};

type ImageHotspot = {
  id: string;
  label?: string;
  x: number;
  y: number;
  width: number;
  height: number;
  action: "link" | "popup" | "layer";
  url?: string;
  popup_image_url?: string;
  popup_title?: string;
  popup_max_width_px?: number;
  visible_outline?: boolean;
};

type SnsPlatform =
  | "facebook"
  | "instagram"
  | "youtube"
  | "tiktok"
  | "x"
  | "linkedin"
  | "kakao"
  | "custom";

type SnsItem = {
  id: string;
  platform: SnsPlatform;
  url: string;
  label?: string;
};

type GridCell = {
  id: string;
  type: CellType;
  span: number;
  width_percent?: number;
  /** 모바일에서만 사용하는 최상위 칸 너비 */
  mobile_width_percent?: number;
  /**
   * 모바일에서만 사용하는 레이아웃 보정값.
   * 콘텐츠·URL·색상·글꼴 종류는 공통값으로 유지합니다.
   */
  mobile_overrides?: Partial<GridCell>;
  text?: string;
  rich_text_html?: string;
  mobile_text?: string;
  url?: string;

  /** 버튼 셀 이동 방식: 사이트 페이지 / 현재 페이지 레이어 / 외부 주소 */
  button_link_type?: "page" | "section" | "external";
  /** page이면 page slug, section이면 layer slug, external이면 URL */
  button_link_value?: string;

  image_url?: string;
  image_size_percent?: number;
  image_fit?: "scale" | "width" | "contain" | "cover" | "fill";
  /** true이면 같은 레이아웃의 빈 칸/옆 칸 폭을 무시하고 이 이미지를 레이어 전체 폭으로 표시 */
  image_fill_layer?: boolean;
  /** 이미지 셀 안에서 마우스로 이동한 가로/세로 위치(%) */
  image_position_x?: number;
  image_position_y?: number;
  /** URL이 있어도 링크 이동을 켜거나 끌 수 있습니다. */
  link_enabled?: boolean;
  popup_enabled?: boolean;
  popup_image_url?: string;
  popup_title?: string;
  popup_max_width_px?: number;
  image_hotspots?: ImageHotspot[];
  image_overlay_enabled?: boolean;
  /** 휴대폰에서 이미지가 터치 가능함을 알려주는 움직이는 아이콘 */
  click_hint_enabled?: boolean;
  click_hint_icon?: "pointer" | "arrow" | "plus" | "zoom";
  click_hint_position?: "top-left" | "top-right" | "bottom-left" | "bottom-right" | "custom";
  click_hint_x_percent?: number;
  click_hint_y_percent?: number;
  click_hint_size_px?: number;
  click_hint_background_color?: string;
  click_hint_text_color?: string;
  click_hint_animation?: "none" | "pulse" | "bounce" | "slide";
  click_hint_interval_seconds?: number;
  click_hint_stop_after_tap?: boolean;
  click_hint_link_type?: "none" | "external" | "page" | "section";
  click_hint_link_value?: string;
  logo_size_px?: number;
  display_mode?:
    | "text"
    | "image"
    | "background-image"
    | "auto-slider"
    | "gallery"
    | "video-carousel"
    | "map-section"
    | "image-scroll"
    | "service-card"
    | "business-hours"
    | "restaurant-menu"
    | "catering-menu"
    | "catering-request-form";

  /** DoorDash 스타일 메뉴 셀에서 사용할 방식 */
  restaurant_menu_menu_enabled?: boolean;
  restaurant_menu_pickup_enabled?: boolean;
  restaurant_menu_delivery_enabled?: boolean;

  /** Catering Request Form 전용 배경색 */
  catering_request_outer_background_color?: string;
  catering_request_form_background_color?: string;

  /** Catering Request Form에서 각 입력 항목을 웹사이트에 표시할지 여부 */
  catering_request_fields?: {
    customer_name?: boolean;
    customer_phone?: boolean;
    customer_email?: boolean;
    company?: boolean;
    event_date?: boolean;
    event_time?: boolean;
    guest_count?: boolean;
    occasion?: boolean;
    interested_category?: boolean;
    interested_menu?: boolean;
    catering_service?: boolean;
    budget_per_person?: boolean;
    notes?: boolean;
  };

  gallery_images?: string[];
  /** 갤러리 전용: 이미지 URL과 각 이미지 제목 */
  gallery_items?: GalleryImageItem[];
  /** 이전 버전 호환용 데스크톱 갤러리 열 수 */
  gallery_columns?: 2 | 4 | 6;
  /** 갤러리에서 각 이미지가 차지할 최소 가로 크기(px). 크기에 따라 열 수가 자동 결정됩니다. */
  gallery_item_min_width_px?: number;
  /** 동영상 링크 목록: 개수 제한 없음 */
  video_items?: VideoCarouselItem[];
  /** 한 화면에 표시할 동영상 수: 1~6 */
  video_columns?: 1 | 2 | 3 | 4 | 5 | 6;
  slider_auto_height?: boolean;
  image_scroll_speed?: number;
  image_scroll_direction?: "left" | "right";
  image_scroll_width?: number;
  image_scroll_gap?: number;
  card_description?: string;
  business_hours_file_name?: string;
  business_hours_title?: string;
  business_hours_note?: string;
  business_hours_business_name?: string;
  business_hours_data?: Array<{
    day: string;
    open: string;
    close: string;
    note?: string;
    closed?: boolean;
  }>;
  background_overlay_type?: "none" | "text" | "button";
  overlay_text?: string;
  overlay_font_family?: "sans" | "serif" | "rounded" | "mono";
  overlay_button_style?: "rounded" | "pill" | "square" | "outline";
  overlay_button_color?: string;
  overlay_button_text_color?: string;
  overlay_buttons?: OverlayButton[];
  overlay_button_gap?: number;
  background_image_blur?: number;
  background_image_effect?: "original" | "blur" | "out-focus" | "in-focus";
  /** 전체 배경 이미지 표시 방식 */
  background_image_fit?: "width" | "contain" | "cover" | "scale" | "fill";
  /** 직접 크기 모드에서 사용하는 배경 이미지 크기(%) */
  background_image_size_percent?: number;
  background_image_focus_x?: number;
  background_image_focus_y?: number;
  overlay_text_horizontal?: "left" | "center" | "right";
  overlay_text_vertical?: "top" | "middle" | "bottom";
  /** 자유 드래그 위치(셀 내부 %, 중앙 기준). 없으면 기존 9방향 위치를 사용합니다. */
  overlay_text_x_percent?: number;
  overlay_text_y_percent?: number;
  overlay_button_horizontal?: "left" | "center" | "right";
  overlay_button_vertical?: "top" | "middle" | "bottom";
  /** 자유 드래그 위치(셀 내부 %, 버튼 그룹 중앙 기준). */
  overlay_button_x_percent?: number;
  overlay_button_y_percent?: number;
  overlay_button_direction?: "row" | "column";
  overlay_button_width?: number;
  overlay_button_height?: number;
  /** 모바일에서만 사용할 버튼 높이. 비우면 데스크톱 높이 사용 */
  mobile_overlay_button_height?: number;
  overlay_button_font_size?: number;
  overlay_button_group_style?: "rounded" | "pill" | "square" | "outline";
  overlay_button_group_color?: string;
  overlay_button_group_text_color?: string;
  overlay_buttons_visible?: boolean;
  menu_mode?: "text" | "image";
  menu_items?: Array<{
    id: string;
    label: string;
    url?: string;
    link_type?: "section" | "page";
    link_value?: string;
    image_url?: string;
  }>;
  color?: string;
  background_color?: string;
  font_size?: number;
  line_height?: number;
  font_family?: "sans" | "serif" | "rounded" | "mono";
  font_weight?: "normal" | "semibold" | "bold" | "black" | "600";
  font_style?: "normal" | "italic";
  text_decoration?: "none" | "underline";
  button_width_px?: number;
  button_height_px?: number;
  button_no_wrap?: boolean;
  phone_number?: string;
  map_title?: string;
  map_address?: string;
  map_phone?: string;
  map_email?: string;
  map_info_background_color?: string;
  map_sns_items?: SnsItem[];
  sns_items?: SnsItem[];
  sns_icon_size_px?: number;
  sns_icon_gap_px?: number;
  text_align?: TextAlign;
  vertical_align?: VerticalAlign;
  child_cells?: GridCell[];
  child_direction?: "row" | "column";
  size_percent?: number;
  /** 모바일에서만 사용하는 중첩 칸 비율 */
  mobile_size_percent?: number;
  /** 세로로 나눈 안쪽 테이블 전체 높이 */
  nested_height_px?: number;
  /** 모바일에서만 사용하는 중첩 테이블 전체 높이 */
  mobile_nested_height_px?: number;
};

type GridData = {
  id?: string;
  cells: GridCell[];
  height?: "small" | "medium" | "large";
  height_px?: number;
  /** 모바일에서만 사용하는 레이어 높이 */
  mobile_height_px?: number;

  /** 이 레이아웃 아래 간격(px). 다음 레이어와의 공간을 직접 조절합니다. */
  margin_bottom_px?: number;
  /** 모바일에서만 사용하는 이 레이아웃 아래 간격(px) */
  mobile_margin_bottom_px?: number;

  /**
   * 높이 조절 시 레이어 중심을 유지하기 위한 세로 위치값입니다.
   * 높이가 커지면 위쪽으로 절반 이동하고, 작아지면 아래쪽으로 절반 이동합니다.
   */
  center_offset_y_px?: number;

  // 긴 약관·Privacy Policy처럼 내용 길이에 따라 자동으로 늘어나는 레이어
  auto_height?: boolean;

  // 같은 레이어 안의 각 가로 레이아웃마다 너비를 따로 저장합니다.
  layout_width_mode?: "full" | "container";

  // 각 레이아웃에만 적용되는 개별 테두리 설정
  layout_border_enabled?: boolean;
  layout_border_width?: number;
  layout_border_color?: string;
  layout_border_style?: "solid" | "dashed" | "dotted" | "double";
  layout_border_radius?: number;
};

type WebsiteSettings = {
  /**
   * 헤더 로고를 저장하면 홈 화면 설치 아이콘에도 자동 사용됩니다.
   */
  logo_url?: string;
  app_icon_url?: string;
  primary_color?: string;
  secondary_color?: string;
  accent_color?: string;
  font_style?: string;
  button_style?: string;
  layout_width?: string;
  outer_background_color?: string;
  header_background_color?: string;
  header_grid?: GridData;
  header_submenu_enabled?: boolean;
  header_submenu_background_color?: string;
  header_submenu_text_color?: string;
  header_submenu_items?: Array<{
    id: string;
    label: string;
    url: string;
    target_type?: "section" | "page";
    target_value?: string;
    children?: Array<{
      id: string;
      label: string;
      url: string;
      target_type?: "section" | "page";
      target_value?: string;
    }>;
  }>;
  header_height_px?: number;
  header_logo_size_px?: number;
  header_title_font_size_px?: number;
  header_menu_font_size_px?: number;
  header_button_height_px?: number;
  header_vertical_padding_px?: number;
  header_submenu_height_px?: number;
  header_submenu_font_size_px?: number;

  /** 모바일 OPEN/CLOSED floating 버튼 */
  mobile_hours_button_enabled?: boolean;
  /** 예: #business-hours, #hours, /hours, /business/90/website/hours */
  mobile_hours_target_url?: string;

  [key: string]: unknown;
};

