function getMobileButtonText(cell: GridCell) {
  const custom = String(cell.mobile_text || "").trim();
  if (custom) return custom;

  const desktopText = String(cell.text || "버튼").trim();

  if (/^order\s+online$/i.test(desktopText)) {
    return "ORDER";
  }

  return desktopText;
}

function getMobileHeaderHeight(
  websiteSettings: WebsiteSettings | null | undefined,
) {
  const savedMobileHeight = Number(
    websiteSettings?.header_grid?.mobile_height_px,
  );

  if (Number.isFinite(savedMobileHeight) && savedMobileHeight > 0) {
    return Math.max(56, Math.min(600, savedMobileHeight));
  }

  const desktopHeaderHeight = Math.max(
    48,
    Math.min(
      1200,
      Number(
        websiteSettings?.header_grid?.height_px ||
          websiteSettings?.header_height_px ||
          104,
      ),
    ),
  );

  const submenuHeight =
    websiteSettings?.header_submenu_enabled === true
      ? Math.max(
          40,
          Math.min(
            120,
            Number(websiteSettings?.header_submenu_height_px ?? 56),
          ),
        )
      : 0;

  return Math.max(
    56,
    Math.min(600, desktopHeaderHeight - submenuHeight),
  );
}

function HeaderSubmenu({
  websiteSettings,
  businessId,
  previewDevice = "desktop",
  editable = false,
}: {
  websiteSettings: WebsiteSettings;
  businessId?: string | number;
  previewDevice?: "desktop" | "mobile";
  editable?: boolean;
}) {
  const [mobileSubmenuOpen, setMobileSubmenuOpen] = useState(false);

  const submenuHeight = Math.max(
    40,
    Math.min(
      120,
      Number(websiteSettings.header_submenu_height_px ?? 56),
    ),
  );
  const submenuFontSize = Math.max(
    11,
    Math.min(
      30,
      Number(websiteSettings.header_submenu_font_size_px ?? 14),
    ),
  );

  if (!websiteSettings.header_submenu_enabled) return null;

  // 모바일에서는 헤더 안의 햄버거 메뉴가 메뉴/전화/주문 버튼을 한 번에 보여줍니다.
  // 별도 서브메뉴를 다시 표시하면 헤더가 두 줄로 중복되므로 숨깁니다.
  if (previewDevice === "mobile") return null;

  const items = Array.isArray(websiteSettings.header_submenu_items)
    ? websiteSettings.header_submenu_items
    : [];

  const visibleItems =
    items.length > 0
      ? items
      : [
          { id: "home", label: "Home", url: "#home" },
          { id: "about", label: "About", url: "#about" },
          { id: "menu", label: "Menu", url: "#menu" },
          { id: "order", label: "Online Order", url: "#order" },
          { id: "login", label: "Log In", url: "#login" },
        ];

  return (
    <nav
      data-header-submenu="true"
      className={`w-full border-t border-white/10 ${
        editable ? "ring-2 ring-inset ring-blue-400/40" : ""
      }`}
      style={{
        height: `${submenuHeight}px`,
        minHeight: `${submenuHeight}px`,
        maxHeight: `${submenuHeight}px`,
        backgroundColor: String(
          websiteSettings.header_submenu_background_color || "#000000",
        ),
        color: String(
          websiteSettings.header_submenu_text_color || "#ffffff",
        ),
        overflow: "visible",
      }}
    >
      <div
        className="mx-auto flex max-w-5xl items-center justify-center gap-8 px-4"
        style={{
          height: `${submenuHeight}px`,
          minHeight: `${submenuHeight}px`,
          maxHeight: `${submenuHeight}px`,
        }}
      >
        {visibleItems.map((item) => {
          const children = Array.isArray(item.children) ? item.children : [];
          const hasChildren = children.length > 0;

          return (
            <div key={item.id} className="group relative flex min-h-full items-center">
              <a
                href={getHeaderMenuHref(item, businessId)}
                onClick={(event) => {
                  if (editable || hasChildren) event.preventDefault();
                }}
                className="flex items-center gap-1 whitespace-nowrap px-2 font-medium transition hover:opacity-70"
                style={{
                  fontSize: `${submenuFontSize}px`,
                  lineHeight: 1,
                  minHeight: `${submenuHeight}px`,
                }}
              >
                <span>{item.label || "Menu"}</span>
                {hasChildren ? (
                  <span aria-hidden="true" className="text-[10px] opacity-70">
                    ▼
                  </span>
                ) : null}
              </a>

              {hasChildren ? (
                <div
                  className="invisible absolute left-1/2 top-full z-[120] min-w-[190px] -translate-x-1/2 translate-y-1 rounded-xl border border-black/10 p-2 opacity-0 shadow-2xl transition group-hover:visible group-hover:translate-y-0 group-hover:opacity-100"
                  style={{
                    backgroundColor: String(
                      websiteSettings.header_submenu_background_color || "#000000",
                    ),
                    color: String(
                      websiteSettings.header_submenu_text_color || "#ffffff",
                    ),
                  }}
                >
                  {children.map((child) => (
                    <a
                      key={child.id}
                      href={getHeaderMenuHref(child, businessId)}
                      onClick={(event) => {
                        if (editable) event.preventDefault();
                      }}
                      className="block rounded-lg px-3 py-2.5 text-left font-semibold no-underline transition hover:bg-white/10"
                      style={{
                        color: "inherit",
                        fontSize: `${Math.max(
                          11,
                          submenuFontSize - 1,
                        )}px`,
                        lineHeight: 1.25,
                      }}
                    >
                      {child.label || "Submenu"}
                    </a>
                  ))}
                </div>
              ) : null}
            </div>
          );
        })}
      </div>
    </nav>
  );
}



